-- The shared exercise library (stable slugs), ported from the old engine's training/library.ts.
-- Reference data, not personal data. Upserts so a renamed exercise reaches existing projects.

on conflict (id) do update set
  name = excluded.name,
  muscle = excluded.muscle,
  secondary = excluded.secondary,
  equipment = excluded.equipment,
  kind = excluded.kind,
  cardio_modality = excluded.cardio_modality;
